// @ts-ignore
import { DatabaseSync } from "node:sqlite";

const DB_PATH = "/home/user/qwik-app/gallery.db";

// Initialize the database
const db = new DatabaseSync(DB_PATH);

// Initialize table
db.exec(`
  CREATE TABLE IF NOT EXISTS images (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    original_name TEXT NOT NULL,
    original_path TEXT NOT NULL,
    optimized_path TEXT NOT NULL,
    width INTEGER NOT NULL,
    height INTEGER NOT NULL,
    uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
  )
`);

export interface ImageRecord {
  id: number;
  original_name: string;
  original_path: string;
  optimized_path: string;
  width: number;
  height: number;
  uploaded_at: string;
}

export function getImages(): ImageRecord[] {
  const stmt = db.prepare("SELECT * FROM images ORDER BY uploaded_at DESC");
  return stmt.all() as ImageRecord[];
}

export function insertImage(image: Omit<ImageRecord, "id" | "uploaded_at">) {
  const stmt = db.prepare(`
    INSERT INTO images (original_name, original_path, optimized_path, width, height)
    VALUES (?, ?, ?, ?, ?)
  `);
  stmt.run(
    image.original_name,
    image.original_path,
    image.optimized_path,
    image.width,
    image.height
  );
}

import sharp from "sharp";
import { join, extname } from "node:path";
import { existsSync, mkdirSync, writeFileSync } from "node:fs";

const ORIGINAL_DIR = "/home/user/qwik-app/public/gallery/original";
const OPTIMIZED_DIR = "/home/user/qwik-app/public/gallery/optimized";

// Ensure directories exist
function ensureDirs() {
  if (!existsSync(ORIGINAL_DIR)) {
    mkdirSync(ORIGINAL_DIR, { recursive: true });
  }
  if (!existsSync(OPTIMIZED_DIR)) {
    mkdirSync(OPTIMIZED_DIR, { recursive: true });
  }
}

export interface ProcessedImageResult {
  originalName: string;
  originalPath: string;
  optimizedPath: string;
  width: number;
  height: number;
}

export async function processUploadedImage(
  buffer: Buffer,
  originalName: string
): Promise<ProcessedImageResult> {
  ensureDirs();

  const uniqueId = `${Date.now()}-${Math.random().toString(36).substring(2, 15)}`;
  const originalExt = extname(originalName) || ".png";
  const originalFilename = `${uniqueId}${originalExt}`;
  const optimizedFilename = `${uniqueId}.webp`;

  const originalFilePath = join(ORIGINAL_DIR, originalFilename);
  const optimizedFilePath = join(OPTIMIZED_DIR, optimizedFilename);

  // Write original file
  writeFileSync(originalFilePath, buffer);

  // Resize, optimize and convert to WebP
  const info = await sharp(buffer)
    .resize(800, 800, {
      fit: "inside",
      withoutEnlargement: true,
    })
    .webp({ quality: 80 })
    .toFile(optimizedFilePath);

  return {
    originalName,
    originalPath: `/gallery/original/${originalFilename}`,
    optimizedPath: `/gallery/optimized/${optimizedFilename}`,
    width: info.width,
    height: info.height,
  };
}

